def por_seccion(alumnos):
    grupos = {}
    for nombre, seccion in alumnos:
        grupos.setdefault(seccion, []).append(nombre)
    return grupos

por_seccion([["Ana", "A"], ["Luis", "B"], ["Rosa", "A"]])
